export type { ToolIcon }

/** Monochrome by design: seventeen brand palettes over the cream ground
 *  would fight the page, and every one would need a dark-mode exception. */
export function ToolGlyph({
  icon,
  ...props
}: { icon: ToolIcon } & SVGProps<SVGSVGElement>) {
  const glyph = GLYPHS[icon]
  if (!glyph) return null
  return (
    <svg
      viewBox={glyph.vb}
      fill="currentColor"
      aria-hidden
      focusable="false"
      {...props}
    >
      {glyph.d.map((d, i) => (
        <path key={i} d={d} />
      ))}
    </svg>
  )
}

export function hasGlyph(icon?: string): icon is ToolIcon {
  return Boolean(icon && icon in GLYPHS)
}
